    def dashboard():
        u=g.user
        if u['role']=='STUDENT':
            orders=get_db().execute('SELECT o.*,x.name outlet_name FROM orders o JOIN outlets x ON x.id=o.outlet_id WHERE user_id=? ORDER BY o.id DESC LIMIT 5',(u['id'],)).fetchall()
            outlets=get_db().execute('SELECT * FROM outlets WHERE active=1 ORDER BY name').fetchall()
            return render_template('student_dashboard.html',orders=orders,outlets=outlets)
