    @login_required
    @roles('STUDENT')
    def cart_add(item_id):
        db=get_db(); item=db.execute('SELECT m.*,i.quantity stock FROM menu_items m LEFT JOIN inventory_items i ON i.id=m.inventory_id WHERE m.id=? AND m.active=1',(item_id,)).fetchone(); qty=max(1,min(99,int(request.form.get('quantity',1) or 1)))
