    @app.route('/checkout',methods=['GET','POST'])
    @login_required
    @roles('STUDENT')
    def checkout():
        db=get_db(); data=session.get('cart',{})
        if not data.get('items'): flash('Your cart is empty.','error'); return redirect(url_for('cart'))
        if request.method=='POST':
            method=request.form.get('payment_method'); paid=request.form.get('payment_result','success')
