<div class="two-col"><form method="post" class="card pad stack"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="action" value="save"><input type="hidden" name="item_id" value="{{ edit_item.id if edit_item else '' }}"><h2>{{ 'Edit menu item' if edit_item else 'Add a menu item' }}</h2><label>Item name<input name="name" value="{{ edit_item.name if edit_item else '' }}" required></label><label>Description<textarea name="description">{{ edit_item.description if edit_item else '' }}</textarea></label><div class="form-row"><label>Price (₹)<input type="number" name="price" min="0" step="0.01" value="{{ '%.2f'|format(edit_item.price_cents/100) if edit_item else '' }}" required></label><label>Prep minutes<input type="number" name="prep_minutes" min="1" value="{{ edit_item.prep_minutes if edit_item else 10 }}"></label></div><label>Category<input name="category" value="{{ edit_item.category if edit_item else 'General' }}"></label><label class="choice"><input type="checkbox" name="available" {% if not edit_item or edit_item.available %}checked{% endif %}> Available to order</label><button class="button primary">{{ 'Save changes' if edit_item else 'Save menu item' }}</button>{% if edit_item %}<a href="{{ url_for('manage_menu',outlet_id=oid) }}">Cancel edit</a>{% endif %}</form><section class="card pad"><h2>PDF menu</h2><p class="muted">Optional PDF download for students. PDF files only, up to 8 MB.</p><form method="post" enctype="multipart/form-data" class="stack"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="action" value="upload"><input type="file" name="menu_pdf" accept="application/pdf" required><button class="button">Upload PDF</button></form></section></div>
