@app.route('/admin/users',methods=['GET','POST'])
@login_required
@roles('ADMIN')
def admin_users():
    db=get_db(); outlets=db.execute('SELECT * FROM outlets ORDER BY name').fetchall()
    if request.method=='POST':
        action=request.form.get('action'); uid=int(request.form.get('user_id',0) or 0)
        if action=='create':
            role=request.form.get('role'); email=request.form.get('email','').strip().lower(); oid=request.form.get('outlet_id') or None
            if role not in ROLES or '@'+current_app.config['KREA_EMAIL_DOMAIN'] not in email: flash('Invalid role or university email.','error')
            elif role=='DH_MANAGER' and (not oid or not db.execute('SELECT 1 FROM outlets WHERE id=? AND name=?',(oid,'Dining Hall')).fetchone()): flash('Dining Hall Managers must be assigned to Dining Hall.','error')
            else:
                db.execute('INSERT INTO users(name,email,password_hash,role,outlet_id) VALUES(?,?,?,?,?)',(request.form.get('name','').strip(),email,generate_password_hash(request.form.get('password','ChangeMe123!')),role,oid)); db.commit(); audit(g.user['id'],'USER_CREATE','user',None,email); flash('User created.','success')
        elif action=='toggle':
            target=db.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
            if not target: abort(404)
            if target['role']=='ADMIN' and target['active'] and db.execute("SELECT count(*) FROM users WHERE role='ADMIN' AND active=1").fetchone()[0]<=1: flash('Cannot deactivate the final active administrator.','error')
            else: db.execute('UPDATE users SET active=? WHERE id=?',(0 if target['active'] else 1,uid)); db.commit(); audit(g.user['id'],'USER_ACTIVE','user',uid,str(not target['active'])); flash('User status updated.','success')
        elif action=='assign':
            target=db.execute('SELECT role FROM users WHERE id=?',(uid,)).fetchone(); oid=request.form.get('outlet_id') or None
            if target and target['role'] in ('STAFF','DH_MANAGER'):
                if target['role']=='DH_MANAGER' and (not oid or not db.execute('SELECT 1 FROM outlets WHERE id=? AND name=?',(oid,'Dining Hall')).fetchone()): flash('Manager must be assigned to Dining Hall.','error')
                else: db.execute('UPDATE users SET outlet_id=? WHERE id=?',(oid,uid)); db.commit(); audit(g.user['id'],'OUTLET_ASSIGN','user',uid,str(oid)); flash('Assignment updated.','success')
        return redirect(url_for('admin_users'))
    users=db.execute('SELECT u.*,o.name outlet_name FROM users u LEFT JOIN outlets o ON o.id=u.outlet_id ORDER BY u.role,u.name').fetchall()
    return render_template('admin_users.html',users=users,outlets=outlets,roles=ROLES)
