            if target=='READY':
                code=f'{secrets.randbelow(1000000):06d}'; salt=secrets.token_bytes(16); digest=hashlib.pbkdf2_hmac('sha256',code.encode(),salt,200000).hex(); expires=(datetime.now(timezone.utc).replace(tzinfo=None)+timedelta(minutes=30)).strftime('%Y-%m-%d %H:%M:%S')
