    db.execute('INSERT INTO notifications(user_id,title,message,kind) VALUES(?,?,?,?)',(uid,title,message,kind))
    recipient=db.execute('SELECT email FROM users WHERE id=?',(uid,)).fetchone()
    if recipient:
        db.execute('INSERT INTO email_notifications(user_id,recipient,subject,message,order_id) VALUES(?,?,?,?,?)',(uid,recipient['email'],title,message,order_id))
