    outlet_columns={row['name'] for row in db.execute('PRAGMA table_info(outlets)').fetchall()}
    if 'menu_pdf' not in outlet_columns:
        db.execute('ALTER TABLE outlets ADD COLUMN menu_pdf TEXT')
    otp_columns={row['name'] for row in db.execute('PRAGMA table_info(pickup_otps)').fetchall()}
    if 'expires_at' not in otp_columns:
        db.execute("ALTER TABLE pickup_otps ADD COLUMN expires_at TEXT")
        db.execute("UPDATE pickup_otps SET expires_at=? WHERE expires_at IS NULL",((datetime.utcnow()+timedelta(minutes=30)).strftime('%Y-%m-%d %H:%M:%S'),))
    columns={row['name'] for row in db.execute('PRAGMA table_info(orders)').fetchall()}
    if 'cancellation_reason' not in columns:
        db.execute('ALTER TABLE orders ADD COLUMN cancellation_reason TEXT')
    # Upgrade older demo databases from random CF- numbers to one stable sequence.
    # Temporary values avoid collisions with the UNIQUE(order_number) constraint.
    rows=db.execute('SELECT id,order_number FROM orders ORDER BY id').fetchall()
    needs_number_upgrade=any(not re.fullmatch(r'ORDER-[0-9]{6}',row['order_number'] or '') for row in rows)
    if rows and needs_number_upgrade:
        db.execute("UPDATE orders SET order_number='MIGRATING-' || id")
        for sequence,row in enumerate(rows,1):
            db.execute('UPDATE orders SET order_number=? WHERE id=?',(f'ORDER-{sequence:06d}',row['id']))
    db.commit()

def is_krea_email(email, role=None):
    """Validate the role-specific simulated Krea identity."""
    if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email or ''):
        return False
    if role == 'STUDENT': configured='krea.ac.in'
    elif role in ('STAFF','DH_MANAGER','ADMIN'): configured='krea.edu.in'
    else: configured=current_app.config.get('KREA_EMAIL_DOMAINS') or current_app.config.get('KREA_EMAIL_DOMAIN','')
    domains={part.strip().lower().lstrip('@') for part in str(configured).split(',') if part.strip()}
    return email.rsplit('@',1)[-1].lower() in domains

def next_order_number(db):
    """Allocate a visible sequential number while checkout holds SQLite's write lock."""
    row=db.execute("SELECT COALESCE(MAX(CAST(SUBSTR(order_number,7) AS INTEGER)),0)+1 AS next_number FROM orders WHERE order_number GLOB 'ORDER-[0-9]*'").fetchone()
    return f'ORDER-{row["next_number"]:06d}'

def order_workload(db, order_id):
    """Return an order's preparation workload in minutes.

    Lines are treated as parallel where reasonable, so an order contributes the
    slowest line's prep_minutes * quantity rather than every line serially.
    """
    row=db.execute('''SELECT COALESCE(MAX(m.prep_minutes * oi.quantity), 0) AS workload
                     FROM order_items oi JOIN menu_items m ON m.id=oi.menu_item_id
                     WHERE oi.order_id=?''',(order_id,)).fetchone()
    return int(row['workload'] or 0)

def estimate_order_minutes(db, order):
    """Estimate queue wait plus this order's workload for the same outlet.

    Only earlier PENDING, ACCEPTED and PREPARING orders at this outlet count.
    READY, completed, rejected and cancelled orders do not contribute. Two
    preparation lanes model reasonable parallel work. This is an ESTIMATE only;
    staff remain responsible for setting READY.
    """
    active=db.execute('''SELECT id FROM orders
                         WHERE outlet_id=? AND id<>? AND id<?
                         AND status IN ('PENDING','ACCEPTED','PREPARING')
                         ORDER BY id''',(order['outlet_id'],order['id'],order['id'])).fetchall()
    ahead=sum(order_workload(db,row['id']) for row in active)
    current=order_workload(db,order['id']) or int(order['prep_minutes'] or 0)
    return (ahead + PREP_LANES - 1)//PREP_LANES + current

def login_required(fn):
    @wraps(fn)
    def wrapped(*a,**kw):
        if not g.user: return redirect(url_for('login',next=request.path))
        return fn(*a,**kw)
    return wrapped
def roles(*allowed):
    def dec(fn):
        @wraps(fn)
        def wrapped(*a,**kw):
            if not g.user: return redirect(url_for('login'))
            if g.user['role'] not in allowed: abort(403)
            return fn(*a,**kw)
        return wrapped
    return dec
