    @app.route('/uploads/<path:filename>')
    @login_required
    def uploaded_file(filename):
        filename=unquote(filename)
        if not filename.lower().endswith('.pdf'): abort(404)
        # Seeded PDFs live in the project root; manager uploads live in the
        # configured uploads directory. Resolve the stored filename in either
        # location without rewriting spaces or other valid filename characters.
        if os.path.basename(filename) != filename:
            abort(404)
        upload_path=os.path.join(current_app.config['UPLOAD_FOLDER'],filename)
        project_path=os.path.join(current_app.root_path,'..',filename)
        if os.path.isfile(upload_path):
            return send_from_directory(current_app.config['UPLOAD_FOLDER'],filename,as_attachment=False,mimetype='application/pdf')
        if os.path.isfile(project_path):
            return send_from_directory(os.path.abspath(os.path.join(current_app.root_path,'..')),filename,as_attachment=False,mimetype='application/pdf')
        abort(404)
